INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('00e68ee6-35dc-4ff4-9e56-a0b9189d67e7', 'Load the first stream (DASH HEVC) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH HEVC playback.', 'fc56f1b9-31d1-493b-ad07-63db55f22410', '2026-09-02 12:35:42.476812', '2026-09-02 12:35:42.476813');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8a077d7b-15cf-49bb-b8f4-767c066ae87c', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH HEVC playback.', 'fc56f1b9-31d1-493b-ad07-63db55f22410', '2026-09-02 12:35:42.477036', '2026-09-02 12:35:42.477036');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c2425fde-d2e2-4309-b9a3-74c07a4f72d5', 'Clear the browser, load the second stream (DASH AV1) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the DASH AV1 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the DASH AV1 stream loads and media events are captured.', 'fc56f1b9-31d1-493b-ad07-63db55f22410', '2026-09-02 12:35:42.477233', '2026-09-02 12:35:42.477234');
