INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ab3c371d-8787-48f3-9ce2-4382bc337da1', 'Load the first stream (4K HLS HEVC) and capture media events.', 'The player loads the first URL from the list and starts playback of the 4K HLS HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the 4K HLS HEVC playback.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-02 12:32:01.795530', '2026-09-02 12:32:01.795531');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dc372b24-aeed-402c-90c7-510034643566', 'Validate observed events for the first playback and record intermediate result.', 'If the 4K HLS HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the 4K HLS HEVC playback.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-02 12:32:01.795828', '2026-09-02 12:32:01.795830');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('460fa969-da66-4904-b030-d4defcd2cbfb', 'Clear the browser, load the second stream (HLS H264) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the HLS H264 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the HLS H264 stream loads and media events are captured.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-02 12:32:01.796112', '2026-09-02 12:32:01.796113');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0f07f096-d065-445e-9fe0-952870ac7e9f', 'Validate observed events for the second playback and record intermediate result.', 'If the HLS H264 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the HLS H264 playback.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-02 12:32:01.797438', '2026-09-02 12:32:01.797439');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('030df622-a2fe-4d67-844e-747f96fec21f', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the 4K HLS HEVC and HLS H264 playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-02 12:32:01.797759', '2026-09-02 12:32:01.797760');
