INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('121a9f1a-e689-4ed1-92ae-2b882ee201c6', 'Clear the browser, load the second stream (HDR) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the HDR stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the HDR stream loads and media events are captured.', '80eb029c-9f70-4dd7-a616-6a5ef9b31686', '2026-09-02 12:30:48.625442', '2026-09-02 12:30:48.625443');
