INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('954a5f23-6cad-4f0d-b719-ff7b43d9452c', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_Download_InvalidURL.', 'The performance test module should load successfully.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.196921', '2026-09-02 11:08:17.196922');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9f2f192c-df33-42b9-b993-58e5ccad8ac9', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.198115', '2026-09-02 11:08:17.198116');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('98586c45-a136-48f8-979f-ad8c33181f02', 'Retrieve SSH connection details', 'Read the configured SSH method and credentials for the device and make them available for remote verification commands.', 'Valid SSH method and credentials should be retrieved successfully.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.199292', '2026-09-02 11:08:17.199294');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3a80f544-1cd8-4815-b533-76875b63452e', 'Subscribe to application download status events', 'Register for download status notifications at /jsonrpc using {"jsonrpc": "2.0","id": 2,"method": "org.rdk.DownloadManager.1.register","params": {"event": "onAppDownloadStatus", "id": "client.events.1" }}.', 'The event subscription should be established successfully.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.200305', '2026-09-02 11:08:17.200306');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bb9600ed-fc83-447e-bbfc-89a739703aed', 'Prepare the valid and invalid download URLs', 'Build the valid URL from app_download_url and google_bundle, and build the failing URL from invalid_download_url and the same bundle name.', 'Both test URLs should be constructed successfully, with only the valid URL pointing to the application bundle location.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.201348', '2026-09-02 11:08:17.201349');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0e4b405f-5822-4b7d-ac86-68e90d24de1d', 'Clear previously received events', 'Clear the download event buffer before starting the invalid-URL test.', 'Previously buffered events should be removed.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.205439', '2026-09-02 11:08:17.205441');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('97993ad9-644a-4a68-8788-f88b6c64628c', 'Request a download from the invalid URL', 'Submit the invalid URL to org.rdk.DownloadManager.1.download using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<invalid_download_url>/<google_bundle>"}}.', 'The download request should fail rather than return success.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.206558', '2026-09-02 11:08:17.206559');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ef83ab3e-add3-429f-b0c8-c702c715af65', 'Process the invalid-URL download result', 'Execute the invalid-URL download test operation a second time as implemented by the script, then read the returned status and details.', 'The resulting status should remain unsuccessful for the invalid URL.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.207637', '2026-09-02 11:08:17.207638');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('200692b8-a0c5-43ae-bd54-5736b66a01fa', 'Process the invalid-URL download result', 'Execute the invalid-URL download test operation a second time as implemented by the script, then read the returned status and details.', 'The resulting status should remain unsuccessful for the invalid URL.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.208717', '2026-09-02 11:08:17.208718');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c099a25b-2278-496c-b613-8d320f0ed65a', 'Validate the invalid-URL failure event', 'Poll the subscribed event buffer for up to 120 seconds and retrieve the first available event.', 'An onAppDownloadStatus event should be received and should contain DOWNLOAD_FAILURE.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.209733', '2026-09-02 11:08:17.209734');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7feca8d9-a061-47d5-a9fe-51702157f2f0', 'Clear events before the valid download', 'Clear the event buffer after validating the invalid-URL failure and before starting the valid download.', 'The event buffer should contain no stale invalid-URL event.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.210766', '2026-09-02 11:08:17.210768');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('268cd46b-a0cb-490b-ab2c-816da9c1940c', 'Request a download from the valid URL', 'Submit the valid URL to org.rdk.DownloadManager.1.download using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url>/<google_bundle>"}}.', 'The download request should return success and a download ID.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.211718', '2026-09-02 11:08:17.211719');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('955f7681-0ff5-45c4-8b3b-eb81a4f41811', 'Validate the successful download event', 'Poll the event buffer for up to 120 seconds. Confirm that the received onAppDownloadStatus event does not contain DOWNLOAD_FAILURE, then parse its download status entry and obtain downloadId and fileLocator.', 'A non-failure download status event should be received, and it should contain a valid download ID and file locator.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.212038', '2026-09-02 11:08:17.212039');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fcf26f5a-e3e3-433b-8b39-7ed6f1299cf3', 'Match the event to the download request', 'Compare the event downloadId with the returned download ID and confirm that the event file locator contains that download ID.', 'The event download ID should match the request ID, and the file locator should identify the requested package.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.212318', '2026-09-02 11:08:17.212319');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e7b9414b-1c46-488c-a039-583b7f9aac82', 'Delete the downloaded package', 'Delete the package using org.rdk.DownloadManager.delete with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.delete","params":{"fileLocator":"<file_locator>"}}.', 'The package deletion request should return success.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.213323', '2026-09-02 11:08:17.213324');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0616748f-e09d-41f4-bcca-0575bc7d02ea', 'Verify package deletion from storage', 'Execute the remote command ls -l <file_locator> using the configured SSH connection.', 'The command output should contain No such file or directory or cannot access, confirming that the package no longer exists on the device.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.214325', '2026-09-02 11:08:17.214326');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('53b5139b-bd99-4fcb-a19c-3fbbd7b6cc8f', 'Close the download event subscription', 'Disconnect from the download status event stream after all validations are complete.', 'The event subscription should close cleanly and the testcase should finish without an active listener.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-02 11:08:17.214648', '2026-09-02 11:08:17.214649');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ba8319e0-1d2c-4a3b-a91c-e473735334d6', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase ', 'The device reboot preference should be configured according to the test environment requirements.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.955443', '2026-09-02 12:15:16.955444');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('641f6643-6444-4693-8d7d-29dbc35bda3d', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, or org.rdk.AppManager.', 'Each required plugin should become activated successfully.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.956342', '2026-09-02 12:15:16.956343');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('50b169a8-08b2-4a17-b6e3-bd07e7d99ac5', 'Check whether the application is installed', 'Query the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"}. If the derived application ID is present, retain the application; otherwise continue with download and installation.', 'The installed-package query should complete successfully, and the application installation state should be determined.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.957212', '2026-09-02 12:15:16.957212');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1105c7c1-db40-433f-8907-35e09fc01268', 'Download the application bundle when required', 'When the application is not installed, request its download using org.rdk.DownloadManager.1.download with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url>/<google_bundle>"}}.', 'The application bundle should download successfully and return a package reference.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.957413', '2026-09-02 12:15:16.957414');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9888fcfc-7317-45d2-ba2c-9c39f61a3941', 'Install the application bundle when required ', 'Install the downloaded bundle using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<app_id>","version":"0.2.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<PACKAGEMANAGER_FILE_LOCATOR><package_reference>"}}.', 'The application should install successfully.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.957612', '2026-09-02 12:15:16.957613');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8ebed455-54f2-4e0b-8b27-5f7b8205ea16', 'Verify the application installation', 'Query the installed package list again with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and confirm that the application ID is listed.', 'The application ID should appear in the installed package list.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.957802', '2026-09-02 12:15:16.957803');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fef60c84-abf2-468e-82fc-eb132f81f70d', 'Subscribe to application lifecycle events', 'Register for lifecycle state notifications at /jsonrpc using {"jsonrpc": "2.0","id": 9,"method": "org.rdk.AppManager.1.register","params": {"event": "onAppLifecycleStateChanged", "id": "client.events.1" }} and wait 5 seconds for registration readiness.', 'The lifecycle event subscription should be established successfully.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.958610', '2026-09-02 12:15:16.958611');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ad599875-41bb-4e14-b874-c55aeb496334', 'Start the application preload and record the start time', 'Record the current UTC time immediately before sending {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.preloadApp","params":{"appId":"<app_id>"}}.', 'The preload request should return success, and a precise preload start timestamp should be recorded.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.959558', '2026-09-02 12:15:16.959559');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cf58adcd-54d6-4fb3-b5f9-65e4b0f8e24c', 'Poll for the preload lifecycle event', 'Poll the event buffer for up to 120 seconds, selecting an event for the target application that contains onAppLifecycleStateChanged and APP_STATE_PAUSED.', 'A matching paused lifecycle event should be received within the polling period.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.961103', '2026-09-02 12:15:16.961104');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('30ab1a73-dd0e-4e1d-82a5-6602df44f593', 'Record the preload completion time', 'Extract the event timestamp from the received lifecycle event and record it as the preload completion time.', 'The preload completion timestamp should be parsed successfully from the received event.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.962020', '2026-09-02 12:15:16.962021');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6b4f3d13-cd65-489a-8963-86ba081bff89', 'Calculate the preload duration', 'Calculate the elapsed time in milliseconds between the recorded preload start and completion timestamps using completion_time - start_time.', 'The calculated preload duration should be a positive value in milliseconds.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.962213', '2026-09-02 12:15:16.962214');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ecb01170-7d92-48de-86f7-84ad4825605f', 'Validate the preload duration against the configured threshold', 'Compare the calculated duration with APPMANAGER_LAUNCH_THRESHOLD_VALUE + THRESHOLD_OFFSET and require 0 < duration < threshold + offset.', 'The preload duration should be within the configured expected range.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.963039', '2026-09-02 12:15:16.963039');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2739d817-10a3-4659-bfcd-3e528482ade0', 'Terminate the preloaded application', 'Terminate the application using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<app_id>"}}.', 'The application should terminate successfully.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.963240', '2026-09-02 12:15:16.963241');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0690ce6d-e4dd-4cb1-9863-faf4b9d78da9', 'Close the lifecycle event subscription', 'Disconnect from the application lifecycle event stream after the timing and termination checks are complete.', 'The event subscription should close cleanly.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.964076', '2026-09-02 12:15:16.964077');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3eb89b3d-8e15-4569-82ac-9030b5c0fcd6', 'Unload the performance test module', 'Unload the RDKV performance test module after completing the preload timing validation.', 'The performance test module should unload cleanly.', '4da0f3cd-9f93-4105-8ba8-e1e0c6170691', '2026-09-02 12:15:16.964906', '2026-09-02 12:15:16.964907');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8a2e90b0-ed2c-48a0-ad01-1693603b8193', 'STEP 1', 'Load tdkbtr181 and sysutil module.', 'tdkbtr181 and sysutil module should be loaded successfully.', '957fdb99-01d5-4cbc-b5a3-0e945e8a111d', '2026-09-02 10:04:34.506411', '2026-09-02 10:04:34.506412');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fd8112f9-3cf8-451c-a379-344b3142104b', 'STEP 2', 'Check if the prerequisite function is success.', 'The prerequisite should be success.', '957fdb99-01d5-4cbc-b5a3-0e945e8a111d', '2026-09-02 10:04:34.506639', '2026-09-02 10:04:34.506640');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('32f4e94c-65dc-431c-b79b-f9d015555cf2', 'STEP 3', 'Configure ACS to send Reboot Task to reboot the DUT.', 'Should successfully return 200 as status code, a non-empty query response and DUT should initiate reboot. DUT should be up and running after Reboot.', '957fdb99-01d5-4cbc-b5a3-0e945e8a111d', '2026-09-02 10:04:34.506838', '2026-09-02 10:04:34.506839');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('069c844d-f524-4448-8039-f742d88b5804', 'STEP 4', 'Query the last reboot reason to confirm the DUT''s reboot reason as tr069-reboot and ACS-DUT connectivity via ACS.', 'The last reboot reason should be tr069-reboot and resumes ACS-DUT connectivity successfully via ACS.', '957fdb99-01d5-4cbc-b5a3-0e945e8a111d', '2026-09-02 10:04:34.507675', '2026-09-02 10:04:34.507675');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c8ab0932-c98f-478d-8b5a-d5c9043babb3', 'STEP 5', 'Revert the parameters modified during prerequisite to initial values', 'Reverted successfully', '957fdb99-01d5-4cbc-b5a3-0e945e8a111d', '2026-09-02 10:04:34.508519', '2026-09-02 10:04:34.508520');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('adddeeba-f7af-4ade-9e7f-53b82fcd421f', 'STEP 6', 'Unload tdkbtr181 and sysutil module.', 'tdkbtr181 and sysutil module should be loaded successfully.', '957fdb99-01d5-4cbc-b5a3-0e945e8a111d', '2026-09-02 10:04:34.509432', '2026-09-02 10:04:34.509433');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8836d02e-806d-41a6-b64f-b23f7af7cb31', 'Set playback operations for both streams.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for both streams.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-02 12:33:55.762325', '2026-09-02 12:33:55.762326');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b8b83c5f-dea3-489d-b2d4-8dbe4c41a11f', 'Store both stream URLs as a list in PersistentStore.', 'Construct and store both stream URLs as an ordered list in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('70de2ee9-a0a7-4c04-a003-65f4d7b81e62', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7328c6ee-56da-4ea1-ae0c-ade66f52d3eb', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1ea59138-4913-4978-90f6-9ed3f34c908c', 'Load the first stream (DASH H264) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH H264 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH H264 playback.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-02 12:33:55.765110', '2026-09-02 12:33:55.765111');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('84bff137-11dd-42fc-9ede-1a518e148297', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH H264 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH H264 playback.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-02 12:33:55.765951', '2026-09-02 12:33:55.765952');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7bc80622-4dc3-4d1c-8509-a234660fd4ac', 'Clear the browser, load the second stream (DASH HEVC) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the DASH HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the DASH HEVC stream loads and media events are captured.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-02 12:33:55.766807', '2026-09-02 12:33:55.766808');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c604f000-c177-45e3-bdc5-075b256a5401', 'Validate observed events for the second playback and record intermediate result.', 'If the DASH HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH HEVC playback.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-02 12:33:55.767004', '2026-09-02 12:33:55.767005');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('da9e9bbc-db54-4698-a03c-4d159a8b5849', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the DASH H264 and DASH HEVC playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-02 12:33:55.767845', '2026-09-02 12:33:55.767846');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('07c94a89-c789-4232-bd0d-9749693a2ede', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('082568e8-69d9-44b1-8277-15b4d1277517', 'STEP 1', 'Load the modules', 'Modules should be loaded successfully', '7fdd8f8c-c76d-4123-9d09-5f8c38eeb100', '2026-09-02 08:38:15.154616', '2026-09-02 08:38:15.154620');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('af6a3fd5-b369-44cf-a028-f04bffcd3da3', 'STEP 2', 'Check the radio enable status and verify its true', 'Radio enable status is true', '7fdd8f8c-c76d-4123-9d09-5f8c38eeb100', '2026-09-02 08:38:15.155621', '2026-09-02 08:38:15.155623');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3d1a80f4-50cf-404f-a122-e672af585e1d', 'STEP 3', 'Try to connect the WIFI client', 'WiFi client should be connected to gateway   and able to access internet successfully ', '7fdd8f8c-c76d-4123-9d09-5f8c38eeb100', '2026-09-02 08:38:15.156484', '2026-09-02 08:38:15.156485');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('290a169b-547d-4ece-b46f-77d56bb69d37', 'STEP 4', 'Unload the modules', 'Modules should be unloaded successfully', '7fdd8f8c-c76d-4123-9d09-5f8c38eeb100', '2026-09-02 08:38:15.157364', '2026-09-02 08:38:15.157365');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f45b6494-aaad-4127-a3e4-5f1b0145ef86', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_Download_Resume_Lifecycle.', 'The performance test module should load successfully.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.142942', '2026-09-02 11:28:36.142944');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('91cb7186-3062-45e0-ad99-9e0884d80c53', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.143802', '2026-09-02 11:28:36.143803');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('36d1bb51-3460-43a9-9cad-43eac56ee528', 'Construct the application download URL', 'Combine the configured app_download_url with Large_Validation_File to form the bundle URL.', 'The resulting download URL should identify the configured large validation bundle.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.144669', '2026-09-02 11:28:36.144670');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('337e6715-bfb8-438c-9354-2be19d8a3d29', 'Start the application bundle download', 'Request the download using org.rdk.DownloadManager.1.download with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url><Large_Validation_File>"}}.', 'The download request should return success and a valid download ID.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.145529', '2026-09-02 11:28:36.145530');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1dad4491-7634-4089-9de0-7a60b68ad7ea', 'Poll for active download progress', 'For up to progress_wait_time one-second attempts, query the download percentage using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}. Stop polling when the returned numeric value is greater than 0 and less than 100.', 'The download should reach an active in-progress state with a numeric percentage satisfying 0 < progress < 100.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.146311', '2026-09-02 11:28:36.146312');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0841759b-804c-4a69-aeb1-863b2daeff51', 'Pause the active download', 'Pause the download using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.pause","params":{"downloadId":"<download_id>"}}.', 'The pause request should return success.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.147115', '2026-09-02 11:28:36.147116');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('311757e7-6821-4de6-9696-327ca0c8110f', 'Read progress after pausing', 'Wait 3 seconds, then query progress again using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}. Compare the returned value with the progress recorded before pausing.', 'The progress value after the pause should equal the value recorded before the pause, demonstrating that downloading is suspended.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.147884', '2026-09-02 11:28:36.147885');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ca769e36-3723-416b-9d3c-4839c2bd03aa', 'Read progress after resuming', 'Wait 5 seconds, then query progress using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}. Compare the returned value with the paused progress value.', 'The resumed progress should be numeric and greater than the paused progress, demonstrating that downloading has continued.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.148080', '2026-09-02 11:28:36.148081');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a3812129-6279-4a66-803e-6f99279f22c4', 'Complete the pause and resume lifecycle validation', 'Mark the test successful only when the pause request succeeds, progress remains unchanged while paused, the resume request succeeds, and progress advances after resuming.', 'The complete download pause-and-resume lifecycle should be validated successfully.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.148850', '2026-09-02 11:28:36.148850');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f7c515af-c169-4f3c-be1b-2fe227aac802', 'Unload the performance test module', 'Unload the RDKV performance test module after the lifecycle checks finish.', 'The performance test module should unload cleanly.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-02 11:28:36.149654', '2026-09-02 11:28:36.149655');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e01f37a7-e55a-4065-af5b-eaab7b7b2ac4', 'STEP 1', 'Load module', 'Loaded module successfully', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.329446', '2026-09-02 09:54:00.329447');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6ebf6065-1c5c-4fb6-b067-98799ef97f4c', 'STEP 2', 'Check if the current ssid and keypassphrase are same as configured in the device configuration file', 'current ssid and keypassphrase should be same as configured in the device configuration file', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.330349', '2026-09-02 09:54:00.330349');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8aa76375-c756-422b-9ca0-b63b0199f27d', 'STEP 3', 'Connect to WLAN client ', 'Connection should be successful', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.331238', '2026-09-02 09:54:00.331239');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e8d13e1c-7c30-4d40-97bd-e05eda574494', 'STEP 4', 'Get the IP address of the WLAN client', 'Should get the IP address of the WLAN client', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.332097', '2026-09-02 09:54:00.332098');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8b2d2fc2-01c1-41f7-8687-e4bc3fb4ab10', 'STEP 5', 'Get the current LAN IP address DHCP range', 'Should get the current LAN IP address DHCP range', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.332989', '2026-09-02 09:54:00.332990');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('26f3c6f1-4a1b-40da-8a43-6f67d6b6b1c7', 'STEP 6', 'Check whether WLAN IP address is in same DHCP range', 'WLAN IP address should be in same DHCP range', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.333830', '2026-09-02 09:54:00.333831');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5cd74566-cf8c-43b9-9a07-b9be13b742b8', 'STEP 7', 'Get the IP address of the LAN client', 'Should get the IP address of the LAN client', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.334671', '2026-09-02 09:54:00.334671');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0967183c-2c40-4795-8177-285b085272f3', 'STEP 8', 'Check whether LAN IP address is in same DHCP range', ' LAN IP address should be in same DHCP range', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.336173', '2026-09-02 09:54:00.336174');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('79467008-06c9-48ad-af25-f8701a4dc392', 'STEP 9', 'Check TCP from WLAN to LAN', 'TCP from WLAN to LAN is successful', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.337097', '2026-09-02 09:54:00.337098');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ad54b6db-308f-4388-9a17-f8756e786c24', 'STEP 10', 'Check if the throughput is in desirable throughput range.', 'Throughput is within desirable range', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.337926', '2026-09-02 09:54:00.337927');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e1341264-25e5-496e-b47a-6614718c1ed1', 'STEP 11', ' Disconnect the WLAN client', 'Disconnected the WLAN client successfully', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.338862', '2026-09-02 09:54:00.338863');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('993bd15f-06c0-4896-86d9-cc2105561920', 'STEP 12', 'Unload the module', 'Should unload the module successfully', 'd4b1b997-b5c4-44b5-baf2-bd73ed5e56ce', '2026-09-02 09:54:00.339709', '2026-09-02 09:54:00.339709');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('526032bc-1c49-462c-8f46-d83d9ec3761d', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_Cancel_LargeFile_Download.', 'The performance test module should load successfully.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:44.996619', '2026-09-02 10:55:44.996621');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fc59e3ca-caf3-4a0f-b22d-9cd6e1a87ead', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:44.997710', '2026-09-02 10:55:44.997711');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8ea52f51-04a6-43b7-9efb-88ee33fcdf96', 'Retrieve the package storage locator', 'Read PACKAGEMANAGER_FILE_LOCATOR from the device configuration and derive the package directory by retaining the path before /CDL and appending /CDL/.', 'The package storage directory should be resolved successfully.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:44.998719', '2026-09-02 10:55:44.998720');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('708ee158-ad3a-4983-a1cb-8c764ece7b21', 'Retrieve SSH connection details', 'Read the configured SSH method, device IP, username, and password from the device configuration for remote command execution.', 'Valid SSH method and credentials should be available.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:44.999093', '2026-09-02 10:55:44.999094');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('313b27fe-a780-41af-adf4-ba50da89afff', 'Measure initial package storage usage', 'Execute the following remote command against the package storage directory: du -sk <file_locator>/CDL/ | awk ''{print $1}''.', 'The initial package storage usage should be returned as a numeric value in KB.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.000118', '2026-09-02 10:55:45.000119');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('983db9bc-a0a3-4eec-b809-713a933b2d6f', 'Subscribe to application download status events', 'Register for download status notifications at /jsonrpc using the following payload: {"jsonrpc": "2.0","id": 2,"method": "org.rdk.DownloadManager.1.register","params": {"event": "onAppDownloadStatus", "id": "client.events.1" }}.', 'The event subscription should be established successfully.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.001001', '2026-09-02 10:55:45.001002');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b6c7a7eb-705e-4659-8520-df2227fed851', 'Start downloading the large application bundle', 'Request the bundle download using org.rdk.DownloadManager.1.download with the configured URL and the Large_Validation_File name: {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url><Large_Validation_File>"}}.', 'The download request should return success and a download ID.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.001399', '2026-09-02 10:55:45.001401');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('242ee0fe-94b6-441c-bed9-c017be716466', 'Query the download progress', 'Query the download progress for the returned download ID using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}.', 'The progress request should return a numeric percentage greater than 0 and less than 100.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.002320', '2026-09-02 10:55:45.002321');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9d740cd1-a0cd-4dd1-a9d4-5ddb59fc06a9', 'Cancel the active download', 'Cancel the in-progress download using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.cancel","params":{"downloadId":"<download_id>"}}.', 'The cancellation request should return success.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.003290', '2026-09-02 10:55:45.003291');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('98cefe78-f8fd-4c32-853b-9ac2d13740b5', 'Poll for the cancellation status event', 'Poll the subscribed event buffer for up to 120 seconds and retrieve the first available event.', 'An onAppDownloadStatus event should be received and should indicate DOWNLOAD_FAILURE for the cancelled download.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.004158', '2026-09-02 10:55:45.004159');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c378df39-d93f-4dcb-9f09-65b4a846d3c3', 'Validate the cancellation event details', 'Parse the event and compare its downloadId with the requested download ID. Confirm that its fileLocator contains the same download ID. The event data must contain fields equivalent to {"downloadId":"<download_id>","fileLocator":"<file_locator>"} within the download status entry.', 'The event download ID should match the requested ID, and the file locator should identify the cancelled package.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.005132', '2026-09-02 10:55:45.005133');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0fe30f16-b3ce-41b4-ba6d-b69347851a64', 'Delete the cancelled package', 'Delete the package identified by the event file locator using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.delete","params":{"fileLocator":"<file_locator>"}}.', 'The package deletion request should return success.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.006029', '2026-09-02 10:55:45.006030');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5ce70314-158a-4e7c-ac74-9d355c4f660d', 'Verify package deletion from storage', 'Execute the following remote command for the event file locator: ls -l <file_locator>.', 'The command output should contain No such file or directory, confirming that the cancelled package was removed.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.006255', '2026-09-02 10:55:45.006255');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('257cdd98-ef94-496e-be5e-4cf57e25eac8', 'Measure package storage after deletion', 'Execute du -sk <file_locator_directory> | awk ''{print $1}'' against the package storage directory and compare the result with the initial usage.', 'The final package storage usage should be less than or equal to the initial usage.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.007294', '2026-09-02 10:55:45.007295');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0999c5ce-130f-47d3-beb8-599a17452716', 'Close the download event subscription', 'Disconnect from the download status event stream after all validations are complete.', 'The event subscription should close cleanly and the testcase should finish without an active listener.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-02 10:55:45.008253', '2026-09-02 10:55:45.008254');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('87610c64-eefb-44c5-8caa-73643eafeb1f', 'STEP 1', '1. Load the required modules.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('15d2f9f4-bd3e-4613-b10e-ccffd59ab45f', 'STEP 2', ' Get the current telemetry log interval using Device.DeviceInfo.X_RDKCENTRAL-COM_WIFI_TELEMETRY.LogInterval and change it to 300 seconds, i.e. 5 minutes.', 'Telemetry log interval should be retrieved and set to 300 seconds successfully.', '81064aaa-ff2d-4f92-94b5-865383494155', '2026-09-02 08:39:16.171661', '2026-09-02 08:39:16.171664');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('910bbf01-f171-41e2-9e21-44525e347d2a', 'STEP 3', ' Check whether wifihealth.txt file is present under /rdklogs/logs/.', 'wifihealth.txt file should be present', '81064aaa-ff2d-4f92-94b5-865383494155', '2026-09-02 08:39:16.172119', '2026-09-02 08:39:16.172121');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5866353d-af9b-431d-9d7f-8a0d930d911b', 'STEP 4', 'Check for any WIFI_RETRYCOUNT_<index> telemetry marker in wifihealth.txt and read the marker value.', 'WIFI_RETRYCOUNT telemetry marker should be present and its value should be retrieved successfully.', '81064aaa-ff2d-4f92-94b5-865383494155', '2026-09-02 08:39:16.172562', '2026-09-02 08:39:16.172563');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ca699083-b128-4d38-ab20-3c8babe81e8c', 'STEP 5', 'Verify that the WIFI_RETRYCOUNT telemetry marker value is greater than zero.', 'WIFI_RETRYCOUNT telemetry marker value should be greater than zero.', '81064aaa-ff2d-4f92-94b5-865383494155', '2026-09-02 08:39:16.173607', '2026-09-02 08:39:16.173609');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('48697be5-2237-4e82-953b-440d01798914', 'STEP 6', 'Check for any WIFI_MULTIPLERETRYCOUNT_<index> telemetry marker in wifihealth.txt and read the marker value.', 'WIFI_MULTIPLERETRYCOUNT telemetry marker should be present and its value should be retrieved successfully.', '81064aaa-ff2d-4f92-94b5-865383494155', '2026-09-02 08:39:16.174814', '2026-09-02 08:39:16.174816');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('62db98ec-8452-4607-864e-c03ea55ac2ba', 'STEP 7', 'Verify that the WIFI_MULTIPLERETRYCOUNT telemetry marker value is greater than zero.', 'WIFI_MULTIPLERETRYCOUNT telemetry marker value should be greater than zero.', '81064aaa-ff2d-4f92-94b5-865383494155', '2026-09-02 08:39:16.175191', '2026-09-02 08:39:16.175193');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6d4e000a-bef7-41f2-867d-e9637daef4b5', 'STEP 8', 'Revert the telemetry log interval to its original value.', 'Telemetry log interval should be reverted successfully.', '81064aaa-ff2d-4f92-94b5-865383494155', '2026-09-02 08:39:16.176144', '2026-09-02 08:39:16.176146');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0a247a8f-1111-4f5d-a23f-071f1eac4560', 'STEP 9', 'Revert the telemetry enable status to its original value if it was modified during the test.', 'Telemetry Enable status should be reverted successfully if it was changed.', '81064aaa-ff2d-4f92-94b5-865383494155', '2026-09-02 08:39:16.177937', '2026-09-02 08:39:16.177940');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0afb5c20-162c-4537-bc17-6ac87dc9c18e', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_SetZOrder_GetZOrder.', 'The performance test module should load successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.064692', '2026-09-02 12:07:50.064693');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4fea26df-0639-441a-909e-2fde0af2d9cb', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.065629', '2026-09-02 12:07:50.065630');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('676d179a-fd94-4d8c-a777-85d122825e95', 'Check whether the application is installed', 'Query the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"}. If the derived application ID is present, retain the application; otherwise download and install it.', 'The installed-package query should complete successfully, and the application installation state should be determined.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.067412', '2026-09-02 12:07:50.067413');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a8b3adc2-e12b-4d52-b856-e5b831fe629f', 'Download the application bundle when required', 'When the application is not installed, request its download using org.rdk.DownloadManager.1.download with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url>/<google_bundle>"}}.', 'The application bundle should download successfully and return a package reference.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.068344', '2026-09-02 12:07:50.068345');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ae7347cb-b8ed-4ad6-8db2-e58f1105f6e1', 'Install the application bundle when required', 'Install the downloaded bundle using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<app_id>","version":"0.2.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<PACKAGEMANAGER_FILE_LOCATOR><package_reference>"}}.', 'The application should install successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.068992', '2026-09-02 12:07:50.068993');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d22c3009-6470-4b7b-8a43-ac7256144699', 'Install the application bundle when required', 'Install the downloaded bundle using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<app_id>","version":"0.2.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<PACKAGEMANAGER_FILE_LOCATOR><package_reference>"}}.', 'The application should install successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.069933', '2026-09-02 12:07:50.069934');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bd37978c-767d-4333-810e-c1ef2af2dcbe', 'Verify the application installation', 'Query the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and confirm that the application ID is listed.', 'The application ID should appear in the installed package list.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.070204', '2026-09-02 12:07:50.070205');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c23e1a42-6d4e-4603-b164-7623f65df847', 'Launch the application', 'Launch the application using org.rdk.AppManager.launchApp with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<app_id>","intent":"","launchArgs":""}}.', 'The application should launch successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.071094', '2026-09-02 12:07:50.071095');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('34e0d551-e936-4331-acf8-fbb28800a804', 'Retrieve the active application instance ID', 'Query loaded applications using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"}. Select the entry whose appId is the target application and whose lifecycleState is APP_STATE_ACTIVE, and obtain its appInstanceId.', 'An active application entry should be returned with a non-empty application instance ID.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.071294', '2026-09-02 12:07:50.071294');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8c9a0e4b-202a-425b-887d-060e65285cd7', 'Set the application z-order', 'Set the requested z-order using org.rdk.RDKWindowManager.setZOrder with {"jsonrpc":"2.0","id":1,"method":"org.rdk.RDKWindowManager.setZOrder","params":{"clientId":"<app_instance_id>","zOrder":<requested_zorder>}}.', 'The z-order request should return success.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.072238', '2026-09-02 12:07:50.072239');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b81c77f4-80cf-4e1d-a4dc-86041774390c', 'Read back the application z-order', 'Query the assigned z-order using org.rdk.RDKWindowManager.getZOrder with {"jsonrpc":"2.0","id":1,"method":"org.rdk.RDKWindowManager.getZOrder","params":{"clientId":"<app_instance_id>"}}.', 'The get-z-order request should return success and a numeric z-order value.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.072457', '2026-09-02 12:07:50.072457');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fffe78a8-3d89-45b4-b434-3b48935f41ec', 'Compare the requested and returned z-order', 'Compare the value returned by getZOrder with requested_zorder.', 'The returned z-order should exactly match the requested z-order.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.072711', '2026-09-02 12:07:50.072712');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f6adff20-7c1f-4f0a-954e-f231fdf5afa9', 'Terminate the application', 'Terminate the application using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<app_id>"}}.', 'The application should terminate successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.073627', '2026-09-02 12:07:50.073628');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8329c99f-fa2a-4b7e-a1c8-0c97a13ebeb8', 'Unload the performance test module', 'Unload the RDKV performance test module after completing the z-order validation.', 'The performance test module should unload cleanly.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-02 12:07:50.073884', '2026-09-02 12:07:50.073884');
