INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0c261577-744f-4a51-8a9e-817f2833606a', 'STEP 2', 'Get the current telemetry log interval using Device.DeviceInfo.X_RDKCENTRAL-COM_WIFI_TELEMETRY.LogInterval and change it to 300 seconds, i.e. 5 minutes.', 'Telemetry log interval should be retrieved and set to 300 seconds successfully.', 'ff16555f-2d58-48ae-8a9c-e5657d073e99', '2026-09-02 08:39:16.222751', '2026-09-02 08:39:16.222753');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d9207584-7ad3-45dc-98cd-84d8811d81e3', 'STEP 3', 'Verify that the telemetry log interval is updated to 300 seconds.', 'Telemetry log interval should reflect the updated value as 300 seconds.', 'ff16555f-2d58-48ae-8a9c-e5657d073e99', '2026-09-02 08:39:16.225010', '2026-09-02 08:39:16.225015');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6e2d8fef-c1b7-4c8e-bf12-4200c29c25e3', 'STEP 4', 'Check whether wifihealth.txt file is present under /rdklogs/logs/.', 'wifihealth.txt file should be present.', 'ff16555f-2d58-48ae-8a9c-e5657d073e99', '2026-09-02 08:39:16.226441', '2026-09-02 08:39:16.226445');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2fd0446a-0552-4d1a-ad38-cb94c2fc2396', 'STEP 5', 'Check for any WIFI_RETRANSCOUNT_<index> telemetry marker in wifihealth.txt and read the marker value.', 'WIFI_RETRANSCOUNT telemetry marker should be present and its value should be retrieved successfully.', 'ff16555f-2d58-48ae-8a9c-e5657d073e99', '2026-09-02 08:39:16.227647', '2026-09-02 08:39:16.227649');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d41191e9-2cbf-4e4f-bd22-b1a5e261840f', 'STEP 6', 'Verify that the WIFI_RETRANSCOUNT telemetry marker value is greater than zero.', 'WIFI_RETRANSCOUNT telemetry marker value should be greater than zero.', 'ff16555f-2d58-48ae-8a9c-e5657d073e99', '2026-09-02 08:39:16.228108', '2026-09-02 08:39:16.228110');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4bdce347-2fe0-4a6f-8f0d-a4dc59a3b51a', 'STEP 7', 'Check for any WIFI_FAILEDRETRANSCOUNT_<index> telemetry marker in wifihealth.txt and read the marker value.', 'WIFI_FAILEDRETRANSCOUNT telemetry marker should be present and its value should be retrieved successfully.', 'ff16555f-2d58-48ae-8a9c-e5657d073e99', '2026-09-02 08:39:16.229413', '2026-09-02 08:39:16.229415');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5cd6d3b3-4cef-4c00-b460-6f7668c74f6a', 'STEP 8', 'Verify that the WIFI_FAILEDRETRANSCOUNT telemetry marker value is greater than zero.', 'WIFI_FAILEDRETRANSCOUNT telemetry marker value should be greater than zero.', 'ff16555f-2d58-48ae-8a9c-e5657d073e99', '2026-09-02 08:39:16.229872', '2026-09-02 08:39:16.229873');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9f00f113-6d43-40cd-9e7b-aca34acbfab9', 'STEP 9', 'Revert the telemetry log interval to its original value.', 'Telemetry log interval should be reverted successfully.', 'ff16555f-2d58-48ae-8a9c-e5657d073e99', '2026-09-02 08:39:16.230929', '2026-09-02 08:39:16.230931');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4343f686-fce5-42ee-b93b-76c552f736c8', 'STEP 10', 'Revert the telemetry enable status to its original value if it was modified during the test.', 'Telemetry Enable status should be reverted successfully if it was changed.', 'ff16555f-2d58-48ae-8a9c-e5657d073e99', '2026-09-02 08:39:16.231999', '2026-09-02 08:39:16.232001');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('147d1644-8fad-44e9-8a56-929554500010', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_Launch_After_Uninstall.', 'The performance test module should load successfully.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.499959', '2026-09-02 11:40:25.499960');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fb960b5f-5a3e-4ced-b927-976c1a67d99a', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.500912', '2026-09-02 11:40:25.500913');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('15123aac-a592-4bc1-a680-8b1eadeb78e7', 'Check whether the application is installed', 'Query the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"}. If the derived application ID is present, retain the installed application; otherwise continue with download and installation.', 'The installed-package query should complete successfully, and the application installation state should be determined.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.501346', '2026-09-02 11:40:25.501347');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3343e641-6904-48f8-a9ab-b95d3ec99039', 'Download the application bundle when required', 'When the application is not installed, request its download using org.rdk.DownloadManager.1.download with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url>/<google_bundle>"}}.', 'The application bundle should download successfully and return a package reference.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.502300', '2026-09-02 11:40:25.502301');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3be78c7d-5018-4fbb-ba7f-9daca39139cd', 'Install the downloaded application bundle', 'Use the configured package file locator and returned package reference to install the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<app_id>","version":"0.2.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<PACKAGEMANAGER_FILE_LOCATOR><package_reference>"}}.', 'The application should install successfully.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.503275', '2026-09-02 11:40:25.503276');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d7019467-7136-4f2e-a1fd-879881525ed0', 'Verify the application installation', 'Query the installed package list again with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and confirm that the derived application ID is listed.', 'The application ID should appear in the installed package list.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.504197', '2026-09-02 11:40:25.504198');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ac9c1f45-63b9-445e-8799-e9866b56deef', 'Uninstall the application', 'Uninstall the application using org.rdk.AppPackageManager.uninstall with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.uninstall","params":{"packageId":"<app_id>"}}.', 'The uninstall request should return success.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.505144', '2026-09-02 11:40:25.505145');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0c499a00-3ce9-49f2-becc-6fb56e36395e', 'Wait for uninstall completion', 'Wait 5 seconds after the successful uninstall request before attempting to launch the application.', 'The device should have sufficient time to complete removal of the application package.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.506153', '2026-09-02 11:40:25.506154');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b1e92a59-5d4f-4f74-b6ad-db407ea22372', 'Attempt to launch the uninstalled application', 'Send a launch request using org.rdk.AppManager.launchApp with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<app_id>","intent":"","launchArgs":""}}.', 'The launch request should be rejected and should not return success because the application was uninstalled.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.507230', '2026-09-02 11:40:25.507231');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c41ae518-9e56-4732-b2bf-6d3b15578b87', 'Record the negative launch result', 'Mark the test successful when the launch result is not SUCCESS; mark it unsuccessful if the uninstalled application launches successfully.', 'The final testcase result should be successful only when AppManager prevents launching the removed application.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-02 11:40:25.507567', '2026-09-02 11:40:25.507568');
