INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4e29fc49-dc07-4671-9017-6c4b37b9a52f', 'Load the first stream (DASH AV1) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH AV1 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH AV1 playback.', '95a1d783-c3ce-4da9-a2d1-cc806e356b0d', '2026-09-02 12:32:39.025722', '2026-09-02 12:32:39.025723');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9e77bfae-4503-401c-926a-dd734b40bd5e', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH AV1 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH AV1 playback.', '95a1d783-c3ce-4da9-a2d1-cc806e356b0d', '2026-09-02 12:32:39.026609', '2026-09-02 12:32:39.026610');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2c66a647-481e-487c-8868-0e4b29f6df44', 'Clear the browser, load the second stream (DASH VP9 OPUS) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the DASH VP9 OPUS stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the DASH VP9 OPUS stream loads and media events are captured.', '95a1d783-c3ce-4da9-a2d1-cc806e356b0d', '2026-09-02 12:32:39.027560', '2026-09-02 12:32:39.027560');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('34274946-651a-4fa7-a931-e77913df8c89', 'Validate observed events for the second playback and record intermediate result.', 'If the DASH VP9 OPUS stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH VP9 OPUS playback.', '95a1d783-c3ce-4da9-a2d1-cc806e356b0d', '2026-09-02 12:32:39.028351', '2026-09-02 12:32:39.028352');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('880f3095-1477-42c5-9b1d-761171c427d0', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the DASH AV1 and DASH VP9 OPUS playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', '95a1d783-c3ce-4da9-a2d1-cc806e356b0d', '2026-09-02 12:32:39.028575', '2026-09-02 12:32:39.028575');
