INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('966c777d-82dc-4087-baf5-9880f444b03c', 'Load the performance test module	', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_ResourceUsage_Preload_App.', 'The performance test module should load successfully.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.623413', '2026-09-02 12:01:39.623414');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9ac5d775-92d3-4425-aed7-eb8f49d83d60', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, or org.rdk.AppManager.', 'Each required plugin should become activated successfully.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.624300', '2026-09-02 12:01:39.624301');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('74edb347-d177-4bc7-b7b9-cfbe4726e014', 'Check whether the application is installed', 'Query the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"}. If the derived application ID is present, retain the installed application; otherwise continue with download and installation.', 'The installed-package query should complete successfully, and the application installation state should be determined.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.625250', '2026-09-02 12:01:39.625251');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('29d0a2f7-bf81-411c-b362-aab156bdfd68', 'Download the application bundle when required', 'When the application is not installed, request its download using org.rdk.DownloadManager.1.download with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url>/<google_bundle>"}}.', 'The application bundle should download successfully and return a package reference.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.626124', '2026-09-02 12:01:39.626125');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fba26fa3-d841-4faf-9122-a7fbaaff6661', 'Install the downloaded application bundle', 'Use the configured package file locator and returned package reference to install the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<app_id>","version":"0.2.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<PACKAGEMANAGER_FILE_LOCATOR><package_reference>"}}.', 'The application should install successfully.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.627019', '2026-09-02 12:01:39.627021');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2196f948-d3f9-4748-b10d-2e88ace0c35f', 'Verify the application installation', 'Query the installed package list again with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and confirm that the derived application ID is listed.', 'The application ID should appear in the installed package list.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.627937', '2026-09-02 12:01:39.627938');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b20054c3-aa8b-4056-b936-9d10c65c0f74', 'Preload the installed application', 'Preload the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.preloadApp","params":{"appId":"<app_id>"}}.', 'The preload request should return success.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.628801', '2026-09-02 12:01:39.628802');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3e647a6a-1baf-4c85-a754-8a0bf95c9732', 'Validate application resource usage', 'Execute the resource usage validation operation and inspect its returned details against the configured expected limits.', 'The resource usage validation should return success and should not report ERROR; the application resource usage should remain within the expected limit.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.628996', '2026-09-02 12:01:39.628997');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c9379e00-507c-4842-b566-22be0cc2a2bc', 'Terminate the preloaded application', 'Terminate the application using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<app_id>"}}.', 'The application should terminate successfully.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.629892', '2026-09-02 12:01:39.629893');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('aabaa4fe-4615-4ed9-aa6f-6369dc223cec', 'Unload the performance test module', 'Unload the RDKV performance test module after resource validation and application termination.', 'The performance test module should unload cleanly.', 'd03d0a9b-97da-48e3-8c0a-4eec1ee7abee', '2026-09-02 12:01:39.630087', '2026-09-02 12:01:39.630088');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e6d929ea-2d9e-4194-aeef-a0a6cc6ee969', 'Set playback operations for both streams.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for both streams.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-02 12:35:14.028279', '2026-09-02 12:35:14.028280');
