INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8b0775d8-0a04-46af-8fef-81a0454aa7b5', 'Load the first stream (DASH HEVC) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH HEVC playback.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-02 12:35:14.029982', '2026-09-02 12:35:14.029983');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9cdca76e-37e1-4f65-a088-95239ba7b3f7', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH HEVC playback.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-02 12:35:14.030179', '2026-09-02 12:35:14.030179');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('22622ab4-c360-4e6d-87e7-ee922fb159f9', 'Clear the browser, load the second stream (4K HLS HEVC) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the 4K HLS HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the 4K HLS HEVC stream loads and media events are captured.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-02 12:35:14.031111', '2026-09-02 12:35:14.031112');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c4d39fa5-7009-40e9-a188-351737f643e6', 'Validate observed events for the second playback and record intermediate result.', 'If the 4K HLS HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the 4K HLS HEVC playback.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-02 12:35:14.032059', '2026-09-02 12:35:14.032060');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('44cfcf33-f435-406c-b60c-348117b3ecfc', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the DASH HEVC and 4K HLS HEVC playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-02 12:35:14.033593', '2026-09-02 12:35:14.033593');
